# Antiquity polity profiles, part 2: Rome, Italy, Carthage and the Celtic west
from part1 import P, add

add(id="roman-republic", name="Roman Republic", type="republic", yearsActive="509–27 BC",
 summary="The republic that grew from a city on the Tiber into the ruler of Italy and the Mediterranean, governed by elected magistrates and the Senate until civil wars brought Augustus to power.",
 description="Tradition says the Romans expelled their last king in 509 BC and replaced him with two annually elected consuls. By 264 BC Rome controlled peninsular Italy through a network of colonies and allies. The Punic Wars with Carthage (264–146) brought Sicily, Sardinia, Spain and Africa, and wars in the east brought Macedon, Greece and Asia. Conquest enriched the elite and strained the system, leading to the Gracchi reforms, Marius and Sulla's civil war and finally Caesar's dictatorship and murder in 44 BC. Octavian's victory at Actium (31 BC) ended the republic in all but name.",
 conflicts="The Samnite Wars (343–290), the war with Pyrrhus (280–275), the three Punic Wars, including Hannibal's invasion of Italy and Cannae (216), the Macedonian Wars, Caesar's Gallic War (58–50) and the civil wars of 49–31 BC.",
 leaders="Camillus, Scipio Africanus, Cato the Elder, the Gracchi brothers, Marius, Sulla, Pompey, Julius Caesar and Cicero.",
 religion="State priests such as the pontiffs and augurs read the will of the gods for public decisions; Jupiter Optimus Maximus on the Capitol was the chief god, and foreign cults such as Cybele were brought in during crises.",
 culture="Patrician and plebeian families competed for office through the cursus honorum; the client–patron bond and the army of citizen farmers were the backbone of society.",
 literature="Plautus and Terence adapted Greek comedy; Cicero's speeches and letters, Caesar's Commentaries, Lucretius and Catullus made Latin a literary language.",
 art="Realistic portrait busts of old men (veristic portraits) and Greek art taken as booty shaped Roman taste; the Temple of Hercules Victor in Rome dates from the second century BC.",
 ideas="Polybius explained Rome's success by its 'mixed constitution'; Cicero's On the Republic and On Duties adapted Greek Stoic political thought.",
 science="Roman engineers built the Via Appia (312 BC), aqueducts beginning with the Aqua Appia, and concrete that made large vaults possible.",
 story=[{"title":"Crossing the Rubicon","text":"In January 49 BC Caesar led a legion across the Rubicon, the small river marking the border of his province, which was illegal for a general with his army. 'The die is cast,' he is supposed to have said, and the civil war began."}],
 sources="Encyclopaedia Britannica, 'ancient Rome: The Roman Republic'; M. Beard, SPQR (2015); Polybius, Histories, book 6.",
 images=[("Bust of Cicero (1st-cent. BC) - Palazzo Nuovo - Musei Capitolini - Rome 2016.jpg","Marble bust of Cicero, Capitoline Museums","leader"),
         ("Denarius Roman Republic","Silver denarius of the Roman Republic","culture")])

add(id="roman-empire", name="Roman Empire", type="empire", yearsActive="27 BC–AD 395 (undivided)",
 nameByTick={"300": "Roman Empire (Tetrarchy)"},
 summary="The empire of the Caesars, founded by Augustus, which ruled the whole Mediterranean and Europe to the Rhine, Danube and Hadrian's Wall, reorganised around AD 300 by Diocletian's Tetrarchy.",
 description="Augustus kept the forms of the republic while holding supreme power as princeps from 27 BC. Under him and his successors the empire reached its greatest extent under Trajan (AD 117), with about 60 million people. The Pax Romana of the first two centuries brought roads, cities and Roman citizenship, extended to all free men in 212. The third century brought civil war, invasions and inflation, until Diocletian (284–305) divided rule among two senior emperors (Augusti) and two juniors (Caesars). The map for 300 shows the regions of Diocletian, Maximian, Galerius and Constantius.",
 conflicts="Varus lost three legions in the Teutoburg Forest (AD 9); Claudius invaded Britain (43); Titus destroyed Jerusalem (70); Trajan conquered Dacia (101–106); the Marcomannic Wars (166–180) and the crisis of the third century followed.",
 leaders="Augustus (27 BC–AD 14), Claudius, Trajan, Hadrian, Marcus Aurelius, Septimius Severus, Diocletian (284–305) and Constantine I (306–337).",
 religion="The imperial cult joined traditional gods; Mithras and Isis had followers across the empire. Christians were persecuted at times, most severely under Diocletian from 303, before Constantine's Edict of Milan (313) tolerated them.",
 culture="Latin in the west and Greek in the east were the languages of the cities; baths, amphitheatres and the games spread a common way of life from Britain to Syria.",
 literature="Virgil's Aeneid, Horace, Ovid, Livy, Tacitus, Seneca and Juvenal wrote in Latin; Plutarch and Lucian in Greek.",
 art="The Ara Pacis, Trajan's Column, the Pantheon and the Porphyry Tetrarchs in Venice show the arc from Augustan classicism to late antique abstraction.",
 ideas="Roman law, gathered by jurists such as Ulpian and Gaius, became the basis of European civil law; Marcus Aurelius wrote his Stoic Meditations on campaign.",
 science="Ptolemy's Almagest and Geography and Galen's medicine dominated science for 1,300 years; Roman engineers built aqueducts such as the Pont du Gard.",
 story=[{"title":"Four rulers in porphyry","text":"A red porphyry sculpture now set into a corner of St Mark's in Venice shows the four tetrarchs embracing in pairs, identical and hand on sword. It was taken from Constantinople in 1204; one missing foot was later found in Istanbul."}],
 sources="Encyclopaedia Britannica, 'ancient Rome: The Roman Empire'; P. Garnsey and R. Saller, The Roman Empire (2nd ed. 2014); S. Corcoran, The Empire of the Tetrarchs (1996).",
 images=[("Statue-Augustus.jpg","The Augustus of Prima Porta","leader"),
         ("Venice – The Tetrarchs 03.jpg","The Porphyry Tetrarchs, St Mark's, Venice","art"),
         ("Pont du Gard BLS.jpg","The Pont du Gard aqueduct bridge in southern France","culture")])

add(id="etruscans", name="Etruscans", type="league of city-states", yearsActive="c. 900–c. 280 BC (independent)",
 summary="The civilisation of Etruria, between the Arno and the Tiber, a league of rich city-states that dominated central Italy before Rome absorbed them.",
 description="The Etruscans spoke a non-Indo-European language and lived in cities such as Veii, Tarquinia, Caere and Vulci, loosely joined in a league of twelve. They grew rich on iron from Elba and trade with Greeks and Phoenicians, and their kings ruled early Rome. By 500 BC they were losing ground: Greeks defeated their fleet at Cumae in 474 BC, Gauls took the Po valley, and Rome destroyed Veii in 396 BC. By the early third century BC all Etruscan cities were Roman allies.",
 conflicts="The battle of Alalia (c. 540 BC), with Carthage against Greek Phocaeans; defeat at Cumae (474 BC) by Syracuse; wars with Rome from the siege of Veii to Sentinum (295 BC).",
 leaders="The Tarquin kings of Rome were of Etruscan origin; Lars Porsenna of Clusium besieged Rome around 508 BC.",
 religion="Etruscan priests read the will of the gods from livers and lightning (the 'Etruscan discipline'), a lore Rome continued to consult for centuries.",
 culture="Women dined with men and are named in inscriptions, which shocked Greek observers; banquets and funeral games were central to aristocratic life.",
 literature="Etruscan writing survives in about 13,000 inscriptions and the linen book of the Zagreb mummy, readable but only partly understood.",
 art="Painted tombs at Tarquinia, the terracotta Apollo of Veii and the Sarcophagus of the Spouses from Caere are its best-known works.",
 ideas="Rome took from the Etruscans the fasces, the curule chair, gladiatorial combat and the toga.",
 science="Etruscan engineers drained marshes with tunnels (cuniculi) and laid out cities on a grid oriented to the heavens.",
 story=[{"title":"The bronze liver","text":"A bronze model of a sheep's liver found near Piacenza is divided into sections labelled with the names of gods. A priest would compare a sacrificed animal's liver with it to see which god was sending a sign."}],
 sources="Encyclopaedia Britannica, 'Etruscan'; G. Barker and T. Rasmussen, The Etruscans (1998).",
 images=[("Sarcofago degli sposi.jpg","The Sarcophagus of the Spouses from Caere (c. 520 BC)","art"),
         ("Tarquinia tomb painting","Banquet scene from a painted tomb at Tarquinia","culture")])

add(id="italic-peoples", name="Italic peoples (Samnites, Sabines and others)", type="tribal peoples",
 yearsActive="c. 1000–89 BC (Roman citizenship after the Social War)",
 summary="The Oscan- and Umbrian-speaking peoples of the Apennines, above all the Samnites and Sabines, who were Rome's neighbours and fiercest rivals for control of Italy.",
 description="Central and southern Italy was home to many Italic peoples, related in language to the Latins: Sabines, Umbrians, Volsci, Aequi and the Samnite confederation of the southern Apennines. The Sabines were absorbed by Rome by 290 BC. The Samnites fought Rome in three wars between 343 and 290 BC, and joined Pyrrhus and Hannibal against it. After the Social War (91–88 BC), all Italians received Roman citizenship, and Sulla ravaged Samnium for supporting his enemies.",
 conflicts="The Samnite Wars (343–341, 326–304, 298–290 BC), including the Roman humiliation at the Caudine Forks (321 BC) and Sentinum (295 BC); the Social War (91–88 BC).",
 leaders="Gavius Pontius led the Samnites at the Caudine Forks; Gaius Papius Mutilus was a leader of the Italian allies in the Social War.",
 religion="Each people had sacred groves and sanctuaries, such as the Samnite temple and theatre at Pietrabbondante; the Iguvine Tablets record Umbrian rituals.",
 culture="Hill-forts and scattered villages rather than cities; the Samnite 'sacred spring' sent young people to found new settlements.",
 literature="The Iguvine Tablets, in Umbrian, are the longest text in an Italic language other than Latin.",
 art="Samnite armour, with triple-disc breastplates, and painted tombs at Paestum by the Lucanians show their warrior culture.",
 ideas="Rome borrowed the Samnite maniple, a flexible infantry unit, according to ancient writers.",
 science="Agriculture and pastoral transhumance along the drove roads (tratturi) of the Apennines.",
 story=[{"title":"The Caudine Forks","text":"In 321 BC the Samnites trapped a Roman army in a narrow pass and forced every soldier, including the consuls, to walk under a yoke of spears, the worst humiliation a Roman army could suffer."}],
 sources="Encyclopaedia Britannica, 'Samnite', 'Sabini'; E. T. Salmon, Samnium and the Samnites (1967).",
 images=[("Pietrabbondante teatro","The Samnite theatre at Pietrabbondante","art")])

add(id="carthage", name="Carthaginian Empire", type="mercantile republic", yearsActive="c. 814–146 BC",
 summary="The Phoenician city of Carthage in North Africa and its western Mediterranean empire, which held Sardinia, western Sicily and southern Spain until Rome destroyed it in 146 BC.",
 description="Founded by Phoenicians from Tyre, traditionally in 814 BC, Carthage became the leading power of the western Mediterranean, controlling trade routes to Spain's silver mines and the Atlantic. It fought the Greeks of Sicily for centuries. Defeat by Rome in the First Punic War (264–241) cost it Sicily, and Hamilcar Barca then built a new empire in Spain. His son Hannibal invaded Italy in 218 BC and won great victories, but Scipio defeated him at Zama in 202. In the Third Punic War Rome razed the city (146 BC).",
 conflicts="Wars with Syracuse and the Sicilian Greeks, including defeat at Himera (480 BC); the Mercenary War (241–237); the three Punic Wars, with Hannibal's victories at Trebia, Trasimene and Cannae.",
 leaders="Hamilcar Barca, Hasdrubal and Hannibal Barca, who led an army with elephants over the Alps.",
 religion="Baal Hammon and Tanit were the chief gods; the tophet burial grounds, with urns of children's ashes, are still debated as evidence of child sacrifice.",
 culture="Carthage was governed by two elected suffetes and a council; its circular military harbour could hold over 200 warships.",
 literature="Almost all Punic literature was lost; Mago's treatise on agriculture was translated into Latin on the Senate's orders.",
 art="Punic stelae, glass masks and jewellery show Phoenician, Egyptian and Greek influences.",
 ideas="Aristotle praised the Carthaginian constitution as one of the best of his time.",
 science="Carthaginian navigators such as Hanno sailed down the West African coast, and Himilco north to the Atlantic coasts of Europe.",
 story=[{"title":"Carthage must be destroyed","text":"Cato the Elder, alarmed by Carthage's recovery, ended every speech in the Senate, whatever the subject, with the words that Carthage must be destroyed. In 146 BC it was, after a three-year siege."}],
 sources="Encyclopaedia Britannica, 'Carthage'; R. Miles, Carthage Must Be Destroyed (2010).",
 images=[("Hannibal Barca bust","Marble bust traditionally identified as Hannibal","leader"),
         ("Carthage punic ports","The Punic harbours of Carthage","culture")])

add(id="celts", name="Celtic peoples (Gauls, Boii and others)", type="tribal peoples",
 yearsActive="c. 800 BC–1st century BC (continental independence)",
 summary="The Celtic-speaking peoples of the Hallstatt and La Tène cultures, who spread from central Europe across Gaul, Britain, Ireland, northern Italy and as far as Anatolia.",
 description="Iron Age Celtic culture is named after Hallstatt in Austria (c. 800–450 BC) and La Tène in Switzerland (from c. 450 BC). Princes buried with Greek wine vessels at sites such as Vix show trade with the Mediterranean. In the fourth century BC Celts settled the Po valley and sacked Rome (c. 390 BC); others raided Delphi (279 BC) and settled Galatia. Large fortified towns (oppida) developed in the second century BC, before Caesar conquered Gaul in 58–50 BC.",
 conflicts="The sack of Rome under Brennus (c. 390 BC); the invasion of Greece (279 BC); Roman wars in northern Italy ending at Telamon (225 BC); Caesar's Gallic War and the siege of Alesia (52 BC).",
 leaders="Brennus, leader of the Senones; Vercingetorix of the Arverni, who led the Gallic revolt of 52 BC.",
 religion="Druids served as priests, judges and teachers; gods such as Lugus, Taranis and Cernunnos were worshipped in sacred groves and springs.",
 culture="Warrior aristocracies feasted in hill-forts and oppida; the Boii gave their name to Bohemia.",
 literature="The Celts were largely oral; Gaulish inscriptions and the Coligny calendar survive.",
 art="La Tène art is known for its curving abstract designs on metalwork, such as the Battersea Shield and the Gundestrup cauldron.",
 ideas="Caesar reports that druids taught the immortality of the soul and the movements of the stars.",
 science="Celtic smiths made excellent iron swords and chain mail, and wheelwrights made iron-tyred wheels.",
 story=[{"title":"Woe to the vanquished","text":"After the Gauls took Rome around 390 BC, the Romans agreed to pay a thousand pounds of gold. When they complained that the Gauls' weights were rigged, Brennus threw his sword onto the scales and said: 'Vae victis' (woe to the vanquished)."}],
 sources="Encyclopaedia Britannica, 'Celt'; B. Cunliffe, The Ancient Celts (2nd ed. 2018).",
 images=[("Gundestrup antlered figure.jpg","The antlered figure on the Gundestrup cauldron","culture"),
         ("Battersea Shield","The Battersea Shield, La Tène bronze work from the Thames","art")])

add(id="iberians", name="Iberian peoples", type="tribal peoples", yearsActive="c. 6th century BC–19 BC (Roman conquest complete)",
 summary="The Iberians of eastern and southern Spain, Celtiberians of the central plateau, Lusitanians of the west and other pre-Roman peoples of the peninsula.",
 description="Iberian culture developed along the Mediterranean coast from the sixth century BC, influenced by Phoenician and Greek traders, with towns, writing and rich sanctuaries. In the interior Celtiberians and Celtic-speaking peoples lived in fortified towns such as Numantia, and the Lusitanians dominated the west. Carthage conquered the south and east in the third century BC, and Rome then fought for two centuries to subdue the peninsula, completing the conquest under Augustus in 19 BC.",
 conflicts="The Celtiberian Wars and the siege of Numantia (133 BC); the Lusitanian War led by Viriathus (155–139 BC); the Cantabrian Wars (29–19 BC).",
 leaders="Viriathus, the Lusitanian shepherd-general; Indibilis and Mandonius of the Ilergetes, who fought Carthage and then Rome.",
 religion="Sanctuaries with votive bronzes and stone figures, such as Cerro de los Santos, show local gods and devotees.",
 culture="Iberians wrote their own scripts, adapted from Phoenician and Greek, and Iberian mercenaries served Carthage and the Greeks.",
 literature="Iberian inscriptions can be read but the language is not understood; Celtiberian bronze tablets such as Botorrita are the longest texts.",
 art="The Lady of Elche, a painted limestone bust of the fourth century BC, is the most famous Iberian sculpture.",
 ideas="Iberian 'devotio' bound warriors to die with their leader, a custom Roman writers noted.",
 science="The falcata, a curved Iberian sword, was so effective that the Romans adopted the Iberian gladius.",
 story=[{"title":"Numantia","text":"In 134–133 BC Scipio Aemilianus surrounded the Celtiberian town of Numantia with a nine-kilometre wall and starved it out. Most of the survivors chose death rather than surrender, and the city became a Spanish symbol of resistance."}],
 sources="Encyclopaedia Britannica, 'Iberian', 'Celtiberia'; L. A. Curchin, Roman Spain (1991).",
 images=[("Dama de Elche","The Lady of Elche, Iberian bust of the 4th century BC","art")])

add(id="britons", name="Ancient Britons", type="tribal peoples", yearsActive="Iron Age–AD 5th century",
 summary="The Celtic-speaking peoples of Britain, ruled by tribal kings until the Roman conquest from AD 43, with the Dumnonii of the south-west remaining a self-governing civitas.",
 description="Iron Age Britain was divided among tribes such as the Catuvellauni, Trinovantes, Iceni and Dumnonii, who lived in hill-forts and roundhouses and minted their own coins. Caesar raided the island in 55 and 54 BC, and southern kings became Roman clients. Claudius invaded in AD 43, and Boudica's revolt (60–61) failed. The Dumnonii of Devon and Cornwall were lightly Romanised and kept a tribal capital at Exeter (Isca Dumnoniorum).",
 conflicts="Resistance to Caesar under Cassivellaunus; Caratacus's war against Claudius; Boudica's revolt, which burned Colchester, London and St Albans.",
 leaders="Cassivellaunus, Cunobelinus ('Cymbeline'), Caratacus and Boudica of the Iceni.",
 religion="Druids, whose centre on Anglesey was destroyed by the Romans in AD 60; offerings were thrown into rivers and bogs.",
 culture="Hill-forts such as Maiden Castle, roundhouses and chariot warfare, which surprised Caesar.",
 literature="Oral tradition; coins of Cunobelinus carry Latin legends.",
 art="Insular La Tène metalwork such as the Snettisham torc and the Battersea Shield.",
 ideas="Tacitus put a famous critique of Rome in the mouth of the Caledonian leader Calgacus: 'they make a desert and call it peace.'",
 science="Cornish tin was traded to the Mediterranean from the Bronze Age, as the Greek explorer Pytheas reported.",
 story=[{"title":"Boudica","text":"When the Romans flogged Boudica, queen of the Iceni, and raped her daughters, she led a revolt in AD 60 that destroyed three Roman towns. The governor Suetonius Paulinus defeated her army, and she is said to have taken poison."}],
 sources="Encyclopaedia Britannica, 'Britain: Iron Age', 'Dumnonii'; B. Cunliffe, Iron Age Communities in Britain (4th ed. 2005).",
 images=[("Snettisham Great Torc","The Great Torc from Snettisham, Norfolk","art"),
         ("Maiden Castle Dorset aerial","Maiden Castle hill-fort, Dorset","culture")])

add(id="caledonians", name="Caledonians and Picts", type="tribal peoples", yearsActive="1st century AD–9th century",
 summary="The peoples of northern Scotland beyond Roman rule, called Caledonians by Tacitus and Picts by the late third century.",
 description="Agricola's legions marched into Scotland and defeated the Caledonians at Mons Graupius in AD 83 or 84, but Rome never held the Highlands. Hadrian's Wall (from 122) and the Antonine Wall (from 142) marked the frontier. Septimius Severus campaigned north in 208–211 without lasting success. By 297 a Roman writer calls the northern peoples Picti, 'painted ones', and they raided Roman Britain in the fourth century.",
 conflicts="Mons Graupius (AD 83/84); Severus's campaigns (208–211); the 'barbarian conspiracy' of 367, when Picts, Scots and Saxons attacked Britain together.",
 leaders="Calgacus, leader at Mons Graupius in Tacitus's account; Argentocoxos, whose wife traded insults with the empress Julia Domna.",
 religion="Pre-Christian Celtic religion; Pictish symbol stones of later centuries may record older beliefs.",
 culture="Brochs, crannogs and hill-forts; a society of warrior kindreds.",
 literature="No writings survive; Tacitus's Agricola gives the Roman view.",
 art="Later Pictish symbol stones with animals and abstract symbols.",
 ideas="Roman writers saw them as free barbarians at the edge of the world.",
 science="Drystone brochs, round towers up to 13 m tall, were built without mortar.",
 story=[{"title":"They make a desert","text":"Before Mons Graupius, Tacitus has Calgacus tell his men that the Romans are 'robbers of the world' who 'make a desert and call it peace'. The speech is Tacitus's invention, but it is one of the most quoted lines in Latin."}],
 sources="Encyclopaedia Britannica, 'Pict', 'Caledonia'; D. J. Breeze, Roman Scotland (1996); Tacitus, Agricola.",
 images=[("Hadrian's Wall west of Housesteads","Hadrian's Wall near Housesteads, the frontier with the Caledonians","culture")])

add(id="irish", name="Iron Age Ireland (Hibernia)", type="tribal kingdoms", yearsActive="Iron Age–5th century AD",
 summary="Ireland beyond the Roman Empire, divided among many small kingdoms around royal sites such as Tara and Emain Macha.",
 description="Ireland was never conquered by Rome, though Agricola considered it. Its Iron Age society was organised in small kingdoms (túatha) under over-kings, with ceremonial centres at Tara, Emain Macha (Navan Fort) and Dún Ailinne. Roman goods reached Ireland through trade, and by the fourth century Irish raiders and settlers attacked western Britain.",
 conflicts="Cattle raids and wars between kingdoms, remembered in the later Ulster Cycle; raids on Roman Britain in the fourth century.",
 leaders="Legendary kings such as Conn of the Hundred Battles and Cormac mac Airt are placed in this period by later tradition.",
 religion="Druids and filid (poets) kept law and lore; bog bodies such as Old Croghan Man may be sacrificed kings.",
 culture="Cattle were the measure of wealth; ringforts and crannogs were the main settlements.",
 literature="Ogham inscriptions on stone begin in the fourth century; the epics of the Ulster Cycle, written down later, describe an Iron Age world.",
 art="The Broighter gold boat and torc and the Turoe stone show insular La Tène art.",
 ideas="Brehon law, written down later, preserves Iron Age legal ideas of honour price and kinship.",
 science="Long timber trackways crossed bogs, such as the Corlea trackway of 148 BC.",
 story=[{"title":"The Broighter boat","text":"In 1896 two farmworkers ploughing near Lough Foyle found a gold hoard including a tiny gold boat with oars and a mast. It may have been an offering to the sea god Manannán mac Lir."}],
 sources="Encyclopaedia Britannica, 'Ireland: Early Ireland'; B. Raftery, Pagan Celtic Ireland (1994).",
 images=[("Broighter Gold boat","The Broighter gold boat (1st century BC)","art")])
